// The text helpers of the blueprint's generated indexes (./blueprint.ts): where each goes, how it names the modules it
// imports, and how a list too long for one line is broken, as oxfmt breaks it, so no generated file is formatted
// after. Pure.
import { THING_FILES, type Layout, type Lifecycle, type Part, type Thing } from "@capxul/blueprint-tools";
import * as Arr from "effect/Array";
import * as Option from "effect/Option";
import * as Str from "effect/String";
import { BLUEPRINT } from "./sources.ts";

/** One file the blueprint's target writes: its path from the repository's root, and its text. */
export interface Written {
  readonly path: string;
  readonly text: string;
}

/** What `f` keeps of `items`, in order: each item whose `f` is Some. */
export const somes = <A, B>(items: ReadonlyArray<A>, f: (item: A) => Option.Option<B>): Array<B> =>
  Arr.flatMap(items, (item) => Option.toArray(f(item)));

const WIDTH = 120;

/** Each item on a line of its own, indented, with a trailing comma: how oxfmt breaks a list too long for one line. */
const lines = (items: ReadonlyArray<string>): string =>
  Arr.join(
    Arr.map(items, (item) => `  ${item},\n`),
    "",
  );
export const at = (file: string) => `${BLUEPRINT.root}/src/generated/${file}`;
export const first = (from: string) =>
  `// Generated by \`pnpm generate\` from ${from}. Never edit it: change that and run \`pnpm generate\`.\n`;
export const FROM_THINGS = "packages/blueprint/src/things and packages/generate/src/sources.ts";

/** A thing file's module name, as the indexes import it: `invitation/accept` is `InvitationAccept`. */
export const moduleName = (path: string): string =>
  Arr.join(
    Arr.map(Str.split(Str.replace(/\.ts$/, "")(path), /[/-]/), (part) => Str.capitalize(part)),
    "",
  );

/** `export { a, b } from "x";`, broken over lines as oxfmt breaks it when it is too long. */
export const exportFrom = (names: ReadonlyArray<string>, from: string): string => {
  const one = `export { ${Arr.join(names, ", ")} } from "${from}";`;
  return one.length <= WIDTH ? one : `export {\n${lines(names)}} from "${from}";`;
};

/** `prefix(a, b)` as one line, or one argument a line when it is too long. */
export const call = (prefix: string, args: ReadonlyArray<string>, suffix: string): string => {
  const one = `${prefix}(${Arr.join(args, ", ")})${suffix}`;
  return one.length <= WIDTH || args.length === 0 ? one : `${prefix}(\n${lines(args)})${suffix}`;
};

/** `prefix[a, b]suffix` as one line, or one item a line when it is too long. */
export const array = (prefix: string, items: ReadonlyArray<string>, suffix: string): string => {
  const one = `${prefix}[${Arr.join(items, ", ")}]${suffix}`;
  return one.length <= WIDTH ? one : `${prefix}[\n${lines(items)}]${suffix}`;
};

/** A record literal: `{}` when empty, else one entry a line. */
export const record = (entries: ReadonlyArray<readonly [string, string]>): string =>
  entries.length === 0
    ? "{}"
    : `{\n${Arr.join(
        Arr.map(entries, ([key, value]) => `  ${key}: ${value},\n`),
        "",
      )}}`;

/** One of a thing's own files, `values` or `events`, if the thing has it. */
export const partOf = (thing: Thing, file: string): Option.Option<Part> =>
  Option.flatMap(
    Arr.findFirst(THING_FILES, (each) => each === `${file}.ts`),
    (each) => Option.fromNullishOr(thing.parts[each]),
  );

/** A thing of the layout, by its name. */
export const thingOf = (layout: Layout, name: string): Option.Option<Thing> =>
  Arr.findFirst(layout.things, (thing) => thing.name === name);

/** A domain's thing file: a lifecycle, whose machine joins its `machines`, or a part whose names it exports. */
export type Piece =
  | { readonly kind: "lifecycle"; readonly lifecycle: Lifecycle }
  | { readonly kind: "part"; readonly part: Part };

export const pieceOf = (layout: Layout, path: string): Option.Option<Piece> => {
  const [thing, file = ""] = Str.split(path, "/");
  return Option.flatMap(thingOf(layout, thing), (found): Option.Option<Piece> =>
    file === "lifecycle"
      ? Option.map(Option.fromNullishOr(found.lifecycle), (lifecycle) => ({ kind: "lifecycle", lifecycle }))
      : Option.map(partOf(found, file), (part) => ({ kind: "part", part })),
  );
};

/** An operation's name as a record key: quoted, since every name holds a dot. */
export const key = (name: string) => `"${name}"`;
